def unify(term_a, term_b):
    s = {}

    def isvar(t):
        return isinstance(t, str) and t[:1].isupper()

    def walk(t):
        while isvar(t) and t in s:
            t = s[t]
        return t

    def rec(x, y):
        x, y = walk(x), walk(y)
        if x == y:
            return True
        if isvar(x):
            s[x] = y
            return True
        if isvar(y):
            s[y] = x
            return True
        if (isinstance(x, tuple) and isinstance(y, tuple)
                and len(x) == len(y) and x[0] == y[0]):
            return all(rec(xi, yi) for xi, yi in zip(x[1:], y[1:]))
        return False

    return s if rec(term_a, term_b) else None
